     * paid is added to the customers wallet.
     */
    public async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
        const topUpAmount = this.topUpAmount;
        if (!topUpAmount) {
            Offering.logger.warn(
