    ) {}

    /**
     * Runs every hour for a single top up offering. Every customer enrolled into the offering has their
     * usage for the past hour deducted from their wallet, and their wallet refilled if the balance has dropped
     * below the top up threshold.
     */
    @Process(TOP_UP_CHECKER_DIMENSION_TYPE)
    async evaluateTopUps({ data: { scheduleParameters, subject } }: Job<SchedulerEntity>) {
        const { businessID, offeringId } = scheduleParameters as OfferingTopUpCheckerDto;
        OfferingTopUpChecker.logger.log(
            `Starting top up checker for offering: ${offeringId} in business: ${businessID}. Subject: ${subject}`,
        );
        const { data } = await this.customerService.findAllCustomersWithOfferingId({ businessID, offeringId });
        await Promise.all(
            (data ? data : []).map(async (customer: ReadCustomerResponseData) => {
                try {
                    await this.processTopUpForCustomer({ customer, businessID, offeringId });
                } catch (error) {
                    OfferingTopUpChecker.logger.error(serializeError(error));
                    AuditService.publishEvent({
                        message: 'Failed to process the top up for a customer',
                        topic: AuditScope.ERROR,
                        data: [{ error: serializeError(error), customerId: customer?.customerId, businessID }],
                    });
                }
            }),
        );
        OfferingTopUpChecker.logger.log(`Finished top up checker for offering: ${offeringId}`);
    }

    async processTopUpForCustomer({
        customer,
        businessID,
        offeringId,
    }: {
        customer: ReadCustomerResponseData;
        businessID: string;
        offeringId: string;
    }): Promise<void> {
        const { customerId } = customer;
        const { offering } = await this.contractService.findOne({
            customerId,
            businessID,
            offeringId,
            offeringEnrollmentDate: customer?.offeringEnrollmentDate,
            freeTrialEndDate: customer?.freeTrialEndDate,
        });
        await offering.processTopUpUsage({ customer, creditService: this.creditService });
    }

    @OnQueueFailed({ name: TOP_UP_CHECKER_DIMENSION_TYPE })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to determine top up amounts for customers',
            data: [job],
            topic: AuditScope.ERROR,
        });
    }
}

