import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { CreditService } from '../../credit/credit.service.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SupportedMeasurementFrequencies } from '../../scheduler/dto/scheduler.dto.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { DEFAULT_TOP_UP_THRESHOLD, ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering, OfferingPackageEntity } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { OfferingService } from '../offering.service.js';
import { InfluxService } from '../../influx/influx.service.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 1),
    },
}));

describe('Top up offerings', () => {
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeOfferingID = 'fakeOfferingID';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let creditService: CreditService;
    let topUpOffering: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;

    const dimension = {
        dimensionId: 'fakeDimensionId',
        dimensionName: 'fakeDimensionName',
        aggregationInterval: aggregationInterval.hour,
        aggregationMethod: aggregationMethod.sum,
        usageIncrement: '1',
        consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
        rounding: roundingEnum.ceiling,
        consumptionPrice: '1',
    };

    const mockUsage = (value: string) =>
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId: dimension.dimensionId,
                            usage: [
                                {
                                    startTime: new Date().toISOString(),
                                    endTime: new Date().toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );

    const getOffering = (overrides: Partial<ReadOfferingResponseData> = {}) =>
        Offering.getInstance(
            { ...topUpOffering, ...overrides },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        );

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({ invoiceId: '123', message: 'foobar' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'emitOne').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ data: [] }));
    });

    beforeEach(() => {
        topUpOffering = {
            offeringId: fakeOfferingID,
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            dimensions: [dimension],
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            topUpThreshold: '0.2',
        };
        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
            creditBalance: '100',
        };
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    describe('Offering configuration', () => {
        test('The top up threshold defaults to 0.2', () => {
            const entity = new OfferingPackageEntity({
                offeringName: 'foobar',
                businessID: fakeBusinessID,
                offeringId: fakeOfferingID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
            } as OfferingPackageEntity);
            expect(entity.topUpThreshold).toEqual(DEFAULT_TOP_UP_THRESHOLD);
            expect(entity.topUpAmount).toEqual('100');
            const offering = getOffering({ topUpThreshold: undefined });
            expect(offering.topUpThreshold).toEqual(0.2);
            expect(offering.topUpAmount).toEqual(100);
        });
        test('The top up fields are persisted and read back', () => {
            const tag = jest.fn();
            const influxService = {
                getPoint: () => ({ tag, stringField: jest.fn() }),
            } as unknown as InfluxService;
            const entity = new OfferingPackageEntity({
                offeringName: 'foobar',
                businessID: fakeBusinessID,
                offeringId: fakeOfferingID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
                topUpThreshold: '0.5',
            } as OfferingPackageEntity);
            OfferingPackageEntity.transformer(entity, influxService);
            expect(tag).toHaveBeenCalledWith('topUpAmount', '100');
            expect(tag).toHaveBeenCalledWith('topUpThreshold', '0.5');
            const readEntity = OfferingPackageEntity.dbModelToEntity({
                _value: 'foobar',
                businessID: fakeBusinessID,
                offeringId: fakeOfferingID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
                topUpThreshold: '0.5',
            });
            expect(readEntity.topUpAmount).toEqual('100');
            expect(readEntity.topUpThreshold).toEqual('0.5');
        });
        test('A top up amount is required for top up billing cycles', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.topUp,
                    offeringType: OfferingType.usageBased,
                }),
            ).toThrowError();
        });
        test('Top up fields are not allowed on other billing cycles', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.monthly,
                    offeringType: OfferingType.usageBased,
                    topUpAmount: '100',
                }),
            ).toThrowError();
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.annualToDate,
                    offeringType: OfferingType.usageBased,
                    topUpThreshold: '0.2',
                }),
            ).toThrowError();
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.monthly,
                    offeringType: OfferingType.usageBased,
                }),
            ).not.toThrowError();
        });
        test('Subscription offerings cannot use a top up billing cycle', () => {
            expect(() =>
                OfferingService.validateTopUpFields({
                    billingCycle: ValidBillingCycles.topUp,
                    offeringType: OfferingType.subscription,
                    topUpAmount: '100',
                }),
            ).toThrowError();
        });
    });

    describe('Top up', () => {
        test('A balance exactly at the threshold is sufficient', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
            expect(invoicesService.create).not.toBeCalled();
        });
        test('A balance above the threshold is sufficient', async () => {
            const offering = getOffering();
            await offering.topUp({ customer });
            expect(invoicesService.create).not.toBeCalled();
        });
        test('A balance below the threshold is topped up to the top up amount with a credit stored invoice', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: '19.5' } });
            expect(invoicesService.create).toBeCalledTimes(1);
            expect(invoicesService.create).toBeCalledWith(
                expect.objectContaining({
                    businessID: fakeBusinessID,
                    customerId: fakeCustomerID,
                    storePaymentAsCredit: true,
                }),
            );
            const { items } = (invoicesService.create as jest.Mock).mock.calls[0][0];
            expect((items as InvoiceLineItems).getLineItems()).toEqual([
                expect.objectContaining({ name: 'foobar - Top Up', quantity: 1, unitCost: 80.5 }),
            ]);
        });
    });

    describe('Enrollment', () => {
        test('Enrollment registers a single hourly offering level schedule and tops up the wallet', async () => {
            const offering = getOffering();
            await offering.enroll('fakeSubject', { ...customer, creditBalance: '0' });
            expect(schedulerService.create).toBeCalledTimes(1);
            expect(schedulerService.create).toBeCalledWith(
                expect.objectContaining({
                    rate: SupportedMeasurementFrequencies.everyHour,
                    businessID: fakeBusinessID,
                    scheduleParameters: expect.objectContaining({
                        businessID: fakeBusinessID,
                        offeringId: fakeOfferingID,
                    }),
                }),
            );
            const { schedulerID } = (schedulerService.create as jest.Mock).mock.calls[0][0];
            expect(schedulerID).toEqual(fakeOfferingID);
            expect(schedulerID).not.toContain(fakeCustomerID);
            expect(invoicesService.create).toBeCalledTimes(1);
            const { items } = (invoicesService.create as jest.Mock).mock.calls[0][0];
            expect((items as InvoiceLineItems).getLineItems()).toEqual([
                expect.objectContaining({ name: 'foobar - Top Up', quantity: 1, unitCost: 100 }),
            ]);
        });
        test('Every customer enrolled in the offering shares the same schedule', async () => {
            await getOffering().enroll('fakeSubject', { ...customer, creditBalance: '100' });
            const secondOffering = Offering.getInstance(
                topUpOffering,
                'anotherCustomerId',
                fakeBusinessID,
                invoicesService,
                fakeSettings,
                schedulerService,
                customerService,
            );
            await secondOffering.enroll('fakeSubject', {
                ...customer,
                customerId: 'anotherCustomerId',
                creditBalance: '100',
            });
            expect(schedulerService.create).toBeCalledTimes(2);
            const [firstCall] = (schedulerService.create as jest.Mock).mock.calls[0];
            const [secondCall] = (schedulerService.create as jest.Mock).mock.calls[1];
            expect(firstCall.schedulerID).toEqual(secondCall.schedulerID);
        });
    });

    describe('Hourly usage', () => {
        test('Usage is deducted from the wallet, without generating a usage invoice', async () => {
            mockUsage('10');
            const offering = getOffering();
            const customerWithBalance = { ...customer, creditBalance: '100' };
            await offering.processTopUpUsage({ customer: customerWithBalance });
            expect(creditService.create).toBeCalledTimes(1);
            expect(creditService.create).toBeCalledWith(
                expect.objectContaining({ transactionAmount: '-10.00', customerId: fakeCustomerID }),
                expect.anything(),
            );
            expect(customerWithBalance.creditBalance).toEqual('90');
            // The balance is still above the threshold, so no invoice is created
            expect(invoicesService.create).not.toBeCalled();
        });
        test('Usage which is greater than the balance is still deducted in full, and the wallet is refilled', async () => {
            mockUsage('90');
            const offering = getOffering();
            const customerWithBalance = { ...customer, creditBalance: '25' };
            await offering.processTopUpUsage({ customer: customerWithBalance });
            expect(creditService.create).toBeCalledTimes(1);
            expect(creditService.create).toBeCalledWith(
                expect.objectContaining({ transactionAmount: '-90.00' }),
                expect.anything(),
            );
            expect(customerWithBalance.creditBalance).toEqual('-65');
            expect(invoicesService.create).toBeCalledTimes(1);
            const { items, storePaymentAsCredit } = (invoicesService.create as jest.Mock).mock.calls[0][0];
            expect(storePaymentAsCredit).toEqual(true);
            expect((items as InvoiceLineItems).getLineItems()).toEqual([
                expect.objectContaining({ name: 'foobar - Top Up', quantity: 1, unitCost: 165 }),
            ]);
        });
        test('Zero usage does not create a wallet transaction, but still evaluates the top up', async () => {
            mockUsage('0');
            const offering = getOffering();
            await offering.processTopUpUsage({ customer: { ...customer, creditBalance: '1' } });
            expect(creditService.create).not.toBeCalled();
            expect(invoicesService.create).toBeCalledTimes(1);
            const { items } = (invoicesService.create as jest.Mock).mock.calls[0][0];
            expect((items as InvoiceLineItems).getLineItems()).toEqual([
                expect.objectContaining({ name: 'foobar - Top Up', quantity: 1, unitCost: 99 }),
            ]);
        });
        test('The billing flow for a top up offering does not create a usage invoice', async () => {
            mockUsage('5');
            const offering = getOffering();
            await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '100' });
            expect(creditService.create).toBeCalledTimes(1);
            expect(invoicesService.create).not.toBeCalled();
        });
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { Job } from 'bull';
import { OfferingTopUpChecker } from './offeringTopUpChecker.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { TOP_UP_CHECKER_DIMENSION_TYPE } from './dto/offeringTopUpChecker.dto.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';

describe('OfferingTopUpChecker', () => {
    const businessID = 'fakeBusinessID';
    const offeringId = 'fakeOfferingID';
    let checker: OfferingTopUpChecker;
    let customerService: CustomerService;
    let contractService: ContractService;
    let creditService: CreditService;
    const processTopUpUsage = jest.fn();

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [OfferingTopUpChecker],
        })
            .useMocker(createMock)
            .compile();
        checker = module.get<OfferingTopUpChecker>(OfferingTopUpChecker);
        customerService = module.get<CustomerService>(CustomerService);
        contractService = module.get<ContractService>(ContractService);
        creditService = module.get<CreditService>(CreditService);
        jest.spyOn(customerService, 'findAllCustomersWithOfferingId').mockResolvedValue({
            message: 'found',
            data: [
                { customerId: 'customerOne', businessID, creditBalance: '10' },
                { customerId: 'customerTwo', businessID, creditBalance: '100' },
            ],
        });
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(contractService, 'findOne').mockImplementation(async () => ({
            offering: { processTopUpUsage } as unknown as Offering,
        }));
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(checker).toBeDefined();
    });

    it('Evaluates the top up for every customer enrolled in the offering', async () => {
        await checker.evaluateTopUps({
            data: {
                scheduleParameters: { businessID, offeringId, dimensionType: TOP_UP_CHECKER_DIMENSION_TYPE },
            } as unknown as SchedulerEntity,
        } as Job<SchedulerEntity>);
        expect(customerService.findAllCustomersWithOfferingId).toHaveBeenCalledWith({ businessID, offeringId });
        expect(processTopUpUsage).toHaveBeenCalledTimes(2);
        expect(processTopUpUsage).toHaveBeenCalledWith(
            expect.objectContaining({
                customer: expect.objectContaining({ customerId: 'customerOne' }),
                creditService,
            }),
        );
    });

    it('A failure for a single customer does not prevent the other customers from being evaluated', async () => {
        processTopUpUsage.mockRejectedValueOnce(new Error('fake failure'));
        await checker.evaluateTopUps({
            data: {
                scheduleParameters: { businessID, offeringId, dimensionType: TOP_UP_CHECKER_DIMENSION_TYPE },
            } as unknown as SchedulerEntity,
        } as Job<SchedulerEntity>);
        expect(processTopUpUsage).toHaveBeenCalledTimes(2);
    });
});

