public async processTopUpUsage({
    customer,
    creditService,
    startDate,
    endDate,
    skipTopUp,
}: {
    customer?: ReadCustomerResponseData;
    creditService?: CreditService;
    startDate?: Date;
    endDate?: Date;
    skipTopUp?: boolean;
}): Promise<void> {
    const walletService = creditService ? creditService : this.creditService;
    const { currentBillingCycleStartTime, currentBillingCycleEndTime } = Billing.billingCycleToTimeRange(
        ValidBillingCycles.topUp,
    );
    const usageStartDate = startDate ? startDate : new Date(currentBillingCycleStartTime);
    const usageEndDate = endDate ? endDate : new Date(currentBillingCycleEndTime);
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: usageStartDate,
        endDate: usageEndDate,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId ? this.customerId : customer?.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = Offering.roundToCurrency(lineItems.getTotal());
    Offering.logger.log(
        `Top up usage total for customer ${
            customer?.customerId ? customer?.customerId : this.customerId
        } is ${usageTotal} between ${usageStartDate.toISOString()} and ${usageEndDate.toISOString()}`,
    );
    if (usageTotal > 0 && !walletService) {
        Offering.logger.error(
            `No credit service available to deduct the usage of ${usageTotal} for customer ${
                customer?.customerId ? customer?.customerId : this.customerId
            }`,
        );
        AuditService.publishEvent({
            message: 'No credit service available to deduct usage for a top up offering',
            topic: AuditScope.ERROR,
            data: [{ offeringId: this.offeringId, businessID: this.businessID, usageTotal }],
        });
    } else if (usageTotal > 0) {
        const currentBalance = Offering.parseWalletBalance(customer?.creditBalance);
        await walletService.create(
            {
                businessID: this.businessID,
                customerId: this.customerId ? this.customerId : customer?.customerId,
                transactionAmount: (usageTotal * -1).toFixed(2),
                timestamp: usageEndDate.toISOString(),
                metadata: {
                    reason: `Usage for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
                // Usage is always deducted in full, even if it results in a negative wallet balance
                allowNegativeBalance: true,
            },
            false,
        );
        if (customer) {
            customer.creditBalance = Offering.roundToCurrency(currentBalance - usageTotal).toString();
        }
    }
    if (skipTopUp) {
        return;
    }
    await this.topUp({ customer });
}

